// Column list deliberately excludes embedding/embedding_model/embedded_at:
// those are NULL for most rows (only set later by EmbedWorker), and pgx
// can't scan a NULL vector into pgvector-go's non-nullable Vector type -
// callers of UpsertJob never need the embedding anyway.
func (q *Queries) UpsertJob(ctx context.Context, arg UpsertJobParams) (UpsertJobRow, error) {
	row := q.db.QueryRow(ctx, upsertJob,
		arg.Source,
		arg.ExternalID,
		arg.CompanyID,
		arg.CompanyName,
		arg.Title,
		arg.NormalizedTitle,
		arg.Seniority,
		arg.Description,
		arg.Country,
		arg.State,
		arg.City,
		arg.LocationText,
		arg.RemoteType,
		arg.EmploymentType,
		arg.SalaryMin,
		arg.SalaryMax,
		arg.SalaryCurrency,
		arg.ApplyUrl,
		arg.SourceUrl,
		arg.PostedAt,
		arg.ContentHash,
		arg.Fingerprint,
	)
	var i UpsertJobRow
	err := row.Scan(
		&i.ID,
		&i.Source,
		&i.ExternalID,
		&i.CompanyID,
		&i.CompanyName,
		&i.Title,
		&i.NormalizedTitle,
		&i.Seniority,
		&i.Description,
		&i.Country,
		&i.State,
		&i.City,
		&i.LocationText,
		&i.RemoteType,
		&i.EmploymentType,
		&i.SalaryMin,
		&i.SalaryMax,
		&i.SalaryCurrency,
		&i.ApplyUrl,
		&i.SourceUrl,
		&i.PostedAt,
		&i.FirstSeenAt,
		&i.UpdatedAt,
		&i.LastSeenAt,
		&i.ContentHash,
		&i.Status,
		&i.CreatedAt,
		&i.Fingerprint,
		&i.CanonicalJobID,
		&i.Inserted,
	)
	return i, err
}
